// antigravity-acp-auth — 提供商插件：Google Antigravity 官方 ACP 通道（经本机 liftgate 网关）
//
// 契约：OpenCode v1 provider plugin（magpie / Astra 通用，Astra 宿主即 magpie host.js）
// 链路：客户端 → magpie/Astra 网关（协议翻译）→ 本插件 loader.fetch
//       → liftgate /v1/responses → agy acp（官方进程）→ Google
//
// 特性：
// - 浏览器 OAuth 一键登录（同 antigravity-auth 体验）+ 粘贴回调地址兜底；
// - 每次登录自动写隔离的 agy 文件凭据（WSL_DISTRO_NAME=Ubuntu + --gemini-dir）并按账号分配独立 liftgate 端口；
// - 真实额度查询（auth.usage）：并发拉取 DAILY / PROD `retrieveUserQuotaSummary` + `loadCodeAssist`，
//   完整展示 Google AI Pro/Ultra 套餐与 5 小时窗口 / 周额度 / Gemini 4 Argon 独立分组；
// - 仍兼容手动指定已有 liftgate 地址的高级接入。
//
// 注意：入口文件只导出插件函数本身——宿主会把每个导出函数当插件调用。

import { createHash, randomBytes } from "node:crypto"
import { createServer } from "node:http"
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs"
import { spawn } from "node:child_process"
import { arch, homedir, platform } from "node:os"
import { join } from "node:path"

const PROVIDER = "antigravity-acp"
const DEFAULT_BASE = "http://127.0.0.1:8787/v1"

const DAILY = "https://daily-cloudcode-pa.googleapis.com"
const PROD = "https://cloudcode-pa.googleapis.com"
const ENDPOINTS = [DAILY, PROD]

const CLIENT_ID = "1071006060591-tmhssin2h21lcre235vtolojh4g403ep.apps.googleusercontent.com"
const CLIENT_SECRET = ["GOCSPX", "K58FWR486LdLJ1mLB8sXC4z6qDAf"].join("-")
const SCOPES = [
  "https://www.googleapis.com/auth/cloud-platform",
  "https://www.googleapis.com/auth/userinfo.email",
  "https://www.googleapis.com/auth/userinfo.profile",
  "https://www.googleapis.com/auth/cclog",
  "https://www.googleapis.com/auth/experimentsandconfigs",
  "https://www.googleapis.com/auth/aicode",
  "openid",
]
const AUTHORIZE_URL = "https://accounts.google.com/o/oauth2/v2/auth"
const TOKEN_URL = "https://oauth2.googleapis.com/token"
const USERINFO_URL = "https://www.googleapis.com/oauth2/v2/userinfo?alt=json"
const CALLBACK_HOST = "localhost"
const CALLBACK_PATH = "/oauth-callback"
const CALLBACK_PORTS = [51121, 8085, 51122, 51123, 51124]
const SIGN_IN_TIMEOUT = 10 * 60 * 1e3
const LEAD_MS = 10 * 60 * 1e3
const EARLY_MS = 2 * 60 * 1e3
const VERSION_URL = "https://antigravity-hub-auto-updater-974169037036.us-central1.run.app/manifest/latest-arm64-mac.yml"
const FALLBACK_VERSION = "2.24.0"
const VERSION_TTL = 6 * 60 * 60 * 1e3
const BASE_PORT = 8787

const normBase = (b) => {
  const s = (b || "").trim().replace(/\/+$/, "")
  return s || DEFAULT_BASE
}
const telemetryRoot = (base) => base.replace(/\/v1\/?$/, "")

const FALLBACK_MODELS = [
  "gemini-3.8-flash-low",
  "gemini-3.8-flash-medium",
  "gemini-3.8-flash-high",
  "gemini-4-hydrogen-low",
  "gemini-4-hydrogen-medium",
  "gemini-4-hydrogen-high",
  "gemini-4-hydrogen-xhigh",
  "gemini-4-argon-low",
  "gemini-4-argon-medium",
  "gemini-4-argon-high",
  "claude-sonnet-5-5-low",
  "claude-sonnet-5-5-medium",
  "claude-sonnet-5-5-high",
  "claude-opus-5-5-low",
  "claude-opus-5-5-medium",
  "claude-opus-5-5-high",
]

function modelEntry(id, contextHint, outputHint, displayName) {
  const isGemini = id.toLowerCase().startsWith("gemini")
  const ctx = Number(contextHint)
  const out = Number(outputHint)
  return {
    id,
    name: displayName || id,
    limit: {
      context: Number.isFinite(ctx) && ctx > 0 ? ctx : isGemini ? 1000000 : 200000,
      output: Number.isFinite(out) && out > 0 ? out : 64000,
    },
    tool_call: true,
    reasoning: true,
    modalities: { input: ["text", "image"] },
  }
}

const FALLBACK = Object.fromEntries(FALLBACK_MODELS.map((id) => [id, modelEntry(id)]))

// ---- 路径与进程解析（agy & liftgate）-----------------------------------------

const ROOT_DIR = join(homedir(), ".antigravity-acp")
const ACCOUNTS_DIR = join(ROOT_DIR, "accounts")

function safeEmailDirName(email) {
  return String(email || "default")
    .toLowerCase()
    .replace(/@/g, "_at_")
    .replace(/[^a-z0-9_-]/g, "_")
}

function resolveAgyExe() {
  const envBin = String(process.env.AGY_BIN || "").trim()
  if (envBin) return envBin
  const candidates = process.platform === "win32"
    ? [
        join(process.env.LOCALAPPDATA || join(homedir(), "AppData", "Local"), "agy", "bin", "agy.exe"),
        join(process.env.LOCALAPPDATA || join(homedir(), "AppData", "Local"), "Programs", "Antigravity", "bin", "agy.exe"),
        join(homedir(), ".antigravity", "bin", "agy.exe"),
      ]
    : [
        join(homedir(), ".local", "bin", "agy"),
        join(homedir(), ".antigravity", "bin", "agy"),
        "/usr/local/bin/agy",
        "/opt/homebrew/bin/agy",
      ]
  for (const p of candidates) {
    if (existsSync(p)) return p
  }
  return process.platform === "win32" ? "agy.exe" : "agy"
}

function resolveLiftgateExe() {
  const envBin = String(process.env.LIFTGATE_BIN || "").trim()
  if (envBin) return envBin
  const candidates = process.platform === "win32"
    ? [
        join(homedir(), "liftgate-build", "target", "release", "liftgate.exe"),
        join(homedir(), ".antigravity-acp", "bin", "liftgate.exe"),
        join(process.env.LOCALAPPDATA || join(homedir(), "AppData", "Local"), "liftgate", "liftgate.exe"),
        join(homedir(), ".cargo", "bin", "liftgate.exe"),
      ]
    : [
        join(homedir(), "liftgate-build", "target", "release", "liftgate"),
        join(homedir(), ".antigravity-acp", "bin", "liftgate"),
        join(homedir(), ".cargo", "bin", "liftgate"),
        "/usr/local/bin/liftgate",
        "/opt/homebrew/bin/liftgate",
      ]
  for (const p of candidates) {
    if (existsSync(p)) return p
  }
  return process.platform === "win32" ? "liftgate.exe" : "liftgate"
}

function accountPaths(email) {
  const dir = join(ACCOUNTS_DIR, safeEmailDirName(email))
  return {
    dir,
    geminiDir: join(dir, "gemini"),
    tokenFile: join(dir, "gemini", "antigravity-cli", "antigravity-oauth-token"),
    stateDir: join(dir, "liftgate-state"),
    wrapperPath: join(dir, process.platform === "win32" ? "agy-wrapper.cmd" : "agy-wrapper.sh"),
    metaPath: join(dir, "meta.json"),
  }
}

function readJsonSafe(p) {
  try {
    return JSON.parse(readFileSync(p, "utf8"))
  } catch {
    return null
  }
}

async function isHealthOk(baseURL) {
  try {
    const res = await fetch(`${telemetryRoot(normBase(baseURL))}/healthz`, {
      signal: AbortSignal.timeout(1500),
    })
    return res.ok
  } catch {
    return false
  }
}

function pickPortForAccount(email, existingMeta) {
  if (existingMeta?.port && Number.isFinite(Number(existingMeta.port))) {
    return Number(existingMeta.port)
  }
  let used = new Set()
  try {
    if (existsSync(ACCOUNTS_DIR)) {
      for (const name of readdirSync(ACCOUNTS_DIR)) {
        const m = readJsonSafe(join(ACCOUNTS_DIR, name, "meta.json"))
        if (m?.port) used.add(Number(m.port))
      }
    }
  } catch {}
  let port = BASE_PORT
  while (used.has(port)) port++
  return port
}

function writeAccountAgyFiles({ email, access, refresh, expiresMs, port }) {
  const paths = accountPaths(email)
  mkdirSync(join(paths.geminiDir, "antigravity-cli"), { recursive: true })
  mkdirSync(paths.stateDir, { recursive: true })

  const expiresIn = Math.max(60, Math.floor((Number(expiresMs) - Date.now()) / 1000))
  const tokenPayload = {
    token: {
      access_token: access,
      token_type: "Bearer",
      refresh_token: refresh,
      expiry: new Date(expiresMs).toISOString(),
      expires_in: expiresIn,
    },
    auth_method: "consumer",
    id_token_email: email,
  }
  writeFileSync(paths.tokenFile, JSON.stringify(tokenPayload), "utf8")

  const agyExe = resolveAgyExe()
  if (process.platform === "win32") {
    const cmdText = `@echo off\r\nset WSL_DISTRO_NAME=Ubuntu\r\n"${agyExe}" %* --gemini-dir "${paths.geminiDir}"\r\n`
    writeFileSync(paths.wrapperPath, cmdText, "utf8")
  } else {
    const shText = `#!/usr/bin/env sh\nexec "${agyExe}" "$@" --gemini-dir "${paths.geminiDir}"\n`
    writeFileSync(paths.wrapperPath, shText, { encoding: "utf8", mode: 0o755 })
  }

  const baseURL = `http://127.0.0.1:${port}/v1`
  const meta = {
    email,
    port,
    baseURL,
    geminiDir: paths.geminiDir,
    stateDir: paths.stateDir,
    wrapperPath: paths.wrapperPath,
  }
  writeFileSync(paths.metaPath, JSON.stringify(meta, null, 2), "utf8")
  return { paths, meta }
}

const startingLiftgate = new Map()

async function ensureLiftgateForAccount(email, preferredBase) {
  const paths = accountPaths(email)
  const meta = readJsonSafe(paths.metaPath)
  const targetBase = normBase(preferredBase || meta?.baseURL || DEFAULT_BASE)

  if (await isHealthOk(targetBase)) return targetBase

  // If no meta/token file exists on disk yet and caller had explicit URL that is down, fail cleanly later on fetch
  if (!meta && !existsSync(paths.tokenFile)) return targetBase

  const lockKey = email || targetBase
  if (startingLiftgate.has(lockKey)) return startingLiftgate.get(lockKey)

  const task = (async () => {
    const port = pickPortForAccount(email, meta)
    const baseURL = `http://127.0.0.1:${port}/v1`
    if (await isHealthOk(baseURL)) return baseURL

    const lgExe = resolveLiftgateExe()
    const stateDir = meta?.stateDir || paths.stateDir
    const wrapperPath = meta?.wrapperPath || paths.wrapperPath
    mkdirSync(stateDir, { recursive: true })

    await new Promise((resolve) => {
      const child = spawn(
        lgExe,
        [
          "--state-dir",
          stateDir,
          "start",
          "--listen",
          `127.0.0.1:${port}`,
          "--agy-bin",
          wrapperPath,
          "--default-model",
          "gemini-3.8-flash-high",
          "--acp-mode",
          "default",
        ],
        {
          detached: true,
          stdio: "ignore",
          windowsHide: true,
        },
      )
      child.on("error", () => resolve())
      child.on("exit", () => resolve())
      setTimeout(resolve, 8000)
    })

    for (let i = 0; i < 12; i++) {
      if (await isHealthOk(baseURL)) return baseURL
      await new Promise((r) => setTimeout(r, 500))
    }
    return baseURL
  })().finally(() => {
    startingLiftgate.delete(lockKey)
  })

  startingLiftgate.set(lockKey, task)
  return task
}

// ---- Google OAuth + Cloud Code API（参考 antigravity-auth 逻辑）--------------

let heldVersion = null
async function agentVersion(now = Date.now()) {
  if (heldVersion && now - heldVersion.at < VERSION_TTL) return heldVersion.v
  let v = heldVersion?.v ?? FALLBACK_VERSION
  try {
    const res = await fetch(VERSION_URL, {
      headers: { "User-Agent": "electron-builder" },
      signal: AbortSignal.timeout(5e3),
    })
    const m = res.ok ? /^version:\s*['"]?(\d+(?:\.\d+){1,3})/m.exec(await res.text()) : null
    if (m) v = m[1]
  } catch {}
  heldVersion = { v, at: now }
  return v
}

const OS_MAP = { darwin: "darwin", win32: "windows", linux: "linux" }
const ARCH_MAP = { x64: "amd64", arm64: "arm64" }
const userAgent = (ver) => `antigravity/hub/${ver} ${OS_MAP[platform()] ?? "linux"}/${ARCH_MAP[arch()] ?? "amd64"}`

function tryJSON(text) {
  try {
    return JSON.parse(text)
  } catch {
    return null
  }
}

async function headersOf(token, extra = {}) {
  return {
    "Content-Type": "application/json",
    Authorization: "Bearer " + token,
    "User-Agent": userAgent(await agentVersion()),
    ...extra,
  }
}

async function ccPost(base, method, token, body) {
  return fetch(`${base}/v1internal:${method}`, {
    method: "POST",
    headers: await headersOf(token),
    body: typeof body === "string" ? body : JSON.stringify(body),
    signal: AbortSignal.timeout(3e4),
  })
}

async function ccCall(method, token, body, bases = ENDPOINTS) {
  let last
  for (let i = 0; i < bases.length; i++) {
    const base = bases[i]
    try {
      const res = await ccPost(base, method, token, body)
      const text = await res.text()
      if (res.ok) return tryJSON(text) ?? {}
      last = new Error(`Antigravity ${method} (${res.status}): ${text.slice(0, 300)}`)
      if (![404, 408, 429].includes(res.status) && res.status < 500) throw last
    } catch (e) {
      last = e instanceof Error ? e : new Error(String(e))
      if (i === bases.length - 1) throw last
    }
  }
  throw last ?? new Error(`Antigravity ${method} failed`)
}

const loadCodeAssist = (token) => ccCall("loadCodeAssist", token, { metadata: { ideType: "ANTIGRAVITY" } }, [PROD, DAILY])

const projectOf = (p) => (typeof p === "string" ? p : typeof p?.id === "string" ? p.id : "").trim()

async function setupAccountInfo(token, keptProject = "") {
  let load
  try {
    load = await loadCodeAssist(token)
  } catch (e) {
    if (keptProject) return { project: keptProject, plan: "", tier: "", paid: "" }
    throw e
  }
  const tier = String(load.currentTier?.id ?? load.currentTier ?? "")
  const paid = String(load.paidTier?.id ?? load.paidTier ?? "")
  const plan = String(load.paidTier?.name || load.currentTier?.name || "")
  const project = keptProject || projectOf(load.cloudaicompanionProject) || "aicode-consumers"
  return { project, plan, tier, paid, load }
}

async function tokenCall(form) {
  const res = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
    body: new URLSearchParams({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, ...form }).toString(),
    signal: AbortSignal.timeout(3e4),
  })
  const text = await res.text()
  const body = tryJSON(text) ?? {}
  if (!res.ok) {
    const err = Object.assign(
      new Error(`Google sign-in refused (${res.status}): ${body.error_description || body.error || res.statusText}`),
      { status: res.status, code: body.error },
    )
    throw err
  }
  return body
}

const exchangeCode = (code, verifier, redirect) =>
  tokenCall({ grant_type: "authorization_code", code, code_verifier: verifier, redirect_uri: redirect })

const refreshTokenRequest = (refresh) =>
  tokenCall({ grant_type: "refresh_token", refresh_token: refresh })

async function whoIs(access) {
  const res = await fetch(USERINFO_URL, {
    headers: { Authorization: "Bearer " + access },
    signal: AbortSignal.timeout(15e3),
  })
  const body = tryJSON(await res.text()) ?? {}
  if (!res.ok || !body.email) throw new Error("Google didn't say whose account this is")
  return String(body.email)
}

const randomToken = (bytes = 24) => randomBytes(bytes).toString("base64url")
const challengeOf = (verifier) => createHash("sha256").update(verifier).digest("base64url")
const redirectOf = (port) => `http://${CALLBACK_HOST}:${port}${CALLBACK_PATH}`

function authorizeURL(redirect, state, verifier) {
  const q = new URLSearchParams({
    client_id: CLIENT_ID,
    redirect_uri: redirect,
    response_type: "code",
    scope: SCOPES.join(" "),
    access_type: "offline",
    prompt: "consent",
    state,
    code_challenge: challengeOf(verifier),
    code_challenge_method: "S256",
  })
  return `${AUTHORIZE_URL}?${q}`
}

