function readCode(pasted, state) {
  const text = String(pasted ?? "").trim()
  if (!text) return { error: "未提供授权码或回调地址" }
  if (!/[?&=]/.test(text) && !/^https?:/i.test(text)) return { code: text }
  let q
  try {
    q = new URL(text.startsWith("http") ? text : "http://x/?" + text.replace(/^\?/, "")).searchParams
  } catch {
    return { error: "回调地址格式不正确" }
  }
  if (q.get("error")) return { error: q.get("error_description") || q.get("error") }
  if (q.get("state") && q.get("state") !== state) return { error: "回调地址不属于当前登录会话，请重试" }
  return q.get("code") ? { code: q.get("code") } : { error: "地址中未找到 code 参数" }
}

async function finishOAuthSignIn(code, verifier, redirect) {
  const t = await exchangeCode(code, verifier, redirect)
  if (!t.access_token || !t.refresh_token) {
    throw new Error("Google 未返回 refresh_token；请前往 myaccount.google.com/permissions 移除 Antigravity 后重试")
  }
  const email = await whoIs(t.access_token)
  const expires = Date.now() + (t.expires_in > 0 ? t.expires_in : 3600) * 1000
  const s = await setupAccountInfo(t.access_token).catch(() => ({
    project: "aicode-consumers",
    plan: "Antigravity",
    tier: "",
    paid: "",
  }))

  const existingPaths = accountPaths(email)
  const existingMeta = readJsonSafe(existingPaths.metaPath)
  const port = pickPortForAccount(email, existingMeta)
  const { meta } = writeAccountAgyFiles({
    email,
    access: t.access_token,
    refresh: t.refresh_token,
    expiresMs: expires,
    port,
  })
  await ensureLiftgateForAccount(email, meta.baseURL)

  return {
    type: "success",
    provider: PROVIDER,
    refresh: t.refresh_token,
    access: t.access_token,
    expires,
    accountId: email,
    project: s.project,
    plan: s.plan || "Antigravity",
    tier: s.tier,
    paid: s.paid,
    metadata: {
      baseURL: meta.baseURL,
      email,
      port: meta.port,
    },
  }
}

async function browserSignIn() {
  const { server, port } = await listenOnFirstFree(CALLBACK_PORTS)
  const state = randomToken(24)
  const verifier = randomToken(48)
  const redirect = redirectOf(port)
  let waiting = true
  let settle
  const done = new Promise((r) => (settle = r))
  const finish = (result) => {
    if (!waiting) return
    waiting = false
    settle(result)
  }

  server.on("request", async (req, res) => {
    const url = new URL(req.url ?? "/", `http://${CALLBACK_HOST}:${port}`)
    const html = (code, body) => {
      res.writeHead(code, { "Content-Type": "text/html; charset=utf-8" })
      res.end(body)
    }
    if (url.pathname !== CALLBACK_PATH) return res.writeHead(404).end()
    if (!waiting) return html(200, resultPage(false, "登录会话已结束", "请重新发起登录。"))
    const q = url.searchParams
    const fail = (msg) => {
      finish({ type: "failed", error: msg })
      html(200, resultPage(false, "登录未完成", msg))
    }
    if (q.get("state") !== state) return html(200, resultPage(false, "校验失败", "状态参数不匹配，请重新发起登录。"))
    if (q.get("error")) return fail(q.get("error_description") || q.get("error"))
    if (!q.get("code")) return fail("Google 未返回授权码")
    try {
      const r = await finishOAuthSignIn(q.get("code"), verifier, redirect)
      finish(r)
      html(200, resultPage(true, "登录成功", `${r.accountId} 已授权并接入 Antigravity (ACP)，可关闭此页面。`))
    } catch (e) {
      fail(e.message)
    }
  })

  const timer = setTimeout(() => finish({ type: "failed", error: "登录超时" }), SIGN_IN_TIMEOUT)
  done.then(() => {
    clearTimeout(timer)
    setTimeout(() => server.close(), 1e4).unref?.()
  })

  return {
    url: authorizeURL(redirect, state, verifier),
    instructions: "使用 Google 账号授权 Antigravity（官方 ACP 通道，自动隔离凭据并拉起本地 liftgate 网关）。",
    method: "auto",
    callback: () => done,
  }
}

